/** Начинает игру: компьютер делает первую догадку в середине диапазона. */
private fun startGame() {
    val range = readRange() ?: return
    minValue = range.first
    maxValue = range.second
    low = minValue
    high = maxValue
    currentGuess = (low + high) / 2
    attempts = 1
    gameActive = true
    gameFinished = false
    resultMessage = null
    render()
}

/** Ответ «Меньше»: загаданное число находится ниже текущей догадки. */
private fun narrowRangeToLowerHalf() {
    if (!gameActive || gameFinished) return
    high = currentGuess - 1
    makeNextGuess()
}

/** Ответ «Больше»: загаданное число находится выше текущей догадки. */
private fun narrowRangeToUpperHalf() {
    if (!gameActive || gameFinished) return
    low = currentGuess + 1
    makeNextGuess()
}

private fun makeNextGuess() {
    if (low > high) {
        gameActive = false
        gameFinished = true
        resultMessage = getString(R.string.result_contradiction)
        render()
        return
    }
    currentGuess = (low + high) / 2
    attempts++
    render()
}

/** Число попыток, которое гарантирует деление диапазона пополам. */
private fun maxAttempts(): Int {
    var size = maxValue - minValue + 1
    var count = 0
    while (size > 1) {
        size = (size + 1) / 2
        count++
    }
    return count
}

/** Открывает второе Activity, передавая ему границы диапазона. */
private fun openGuessActivity() {
    val range = readRange() ?: return
    minValue = range.first
    maxValue = range.second
    val intent = Intent(this, GuessActivity::class.java).apply {
        putExtra(GuessActivity.EXTRA_MIN, minValue)
        putExtra(GuessActivity.EXTRA_MAX, maxValue)
    }
    @Suppress("DEPRECATION")
    startActivityForResult(intent, REQUEST_GUESS)
}

@Suppress("DEPRECATION")
override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
    super.onActivityResult(requestCode, resultCode, data)
    if (requestCode != REQUEST_GUESS) return
    secondScreenMessage = if (resultCode == RESULT_OK && data != null) {
        val target = data.getIntExtra(GuessActivity.EXTRA_TARGET, 0)
        val tries = data.getIntExtra(GuessActivity.EXTRA_ATTEMPTS, 0)
        if (data.getBooleanExtra(GuessActivity.EXTRA_WON, false)) {
            getString(R.string.second_screen_result_won, target, tries)
        } else {
            getString(R.string.second_screen_result_lost, target)
        }
    } else {
        getString(R.string.second_screen_result_cancelled)
    }
    render()
}

    // фрагмент onCreate: границы диапазона приходят из Intent,
    // при первом запуске загадывается случайное число
    minValue = intent.getIntExtra(EXTRA_MIN, DEFAULT_MIN)
    maxValue = intent.getIntExtra(EXTRA_MAX, DEFAULT_MAX)
    if (maxValue <= minValue) maxValue = minValue + 1

    if (savedInstanceState == null) {
        target = randomTarget()
        currentLow = minValue
        currentHigh = maxValue
    } else {
        target = savedInstanceState.getInt(KEY_TARGET, minValue)
        attempts = savedInstanceState.getInt(KEY_ATTEMPTS, 0)
        currentLow = savedInstanceState.getInt(KEY_LOW, minValue)
        currentHigh = savedInstanceState.getInt(KEY_HIGH, maxValue)
        finished = savedInstanceState.getBoolean(KEY_FINISHED, false)
        won = savedInstanceState.getBoolean(KEY_WON, false)
        hintMessage = savedInstanceState.getString(KEY_HINT)
    }

    subtitleView.text = getString(R.string.guess_subtitle, minValue, maxValue)

/** Обрабатывает нажатие «Проверить» либо начинает новую игру после финала. */
private fun onCheckClicked() {
    if (finished) {
        startNewGame()
        return
    }
    val text = guessInput.text.toString().trim()
    val guess = text.toIntOrNull()
    if (text.isEmpty() || guess == null) {
        hintMessage = getString(R.string.error_empty)
        render()
        return
    }
    if (guess < currentLow || guess > currentHigh) {
        hintMessage = getString(R.string.error_out_of_range)
        render()
        return
    }

    attempts++
    when {
        guess < target -> {
            currentLow = guess + 1
            hintMessage = getString(R.string.hint_greater)
        }
        guess > target -> {
            currentHigh = guess - 1
            hintMessage = getString(R.string.hint_less)
        }
        else -> {
            finished = true
            won = true
            hintMessage = getString(R.string.hint_won, attempts)
            sendResult()
        }
    }
    guessInput.setText("")
    render()
}

private fun randomTarget(): Int = Random.nextInt(minValue, maxValue + 1)

/** Возвращает результат игры на первый экран. */
private fun sendResult() {
    val data = Intent().apply {
        putExtra(EXTRA_TARGET, target)
        putExtra(EXTRA_ATTEMPTS, attempts)
        putExtra(EXTRA_WON, won)
    }
    setResult(RESULT_OK, data)
}
